using EmployeeManagement.Domain.Leaves.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace EmployeeManagement.Infrastructure.Leaves.Configurations;

/// <summary>
/// EF Core configuration for LeaveBalances table.
/// Configures RemainingDays as a computed column generated by the database.
/// </summary>
public class LeaveBalanceConfiguration : IEntityTypeConfiguration<LeaveBalance>
{
    public void Configure(EntityTypeBuilder<LeaveBalance> builder)
    {
        builder.ToTable("LeaveBalances");

        builder.HasKey(lb => lb.Id);
        builder.Property(lb => lb.Id)
            .HasDefaultValueSql("NEWSEQUENTIALID()");

        builder.Property(lb => lb.LeaveYear)
            .IsRequired();

        builder.Property(lb => lb.EntitledDays)
            .HasColumnType("decimal(4,1)")
            .HasDefaultValue(12.0m)
            .IsRequired();

        builder.Property(lb => lb.CarriedOverDays)
            .HasColumnType("decimal(4,1)")
            .HasDefaultValue(0.0m)
            .IsRequired();

        builder.Property(lb => lb.UsedDays)
            .HasColumnType("decimal(4,1)")
            .HasDefaultValue(0.0m)
            .IsRequired();

        builder.Property(lb => lb.PendingDays)
            .HasColumnType("decimal(4,1)")
            .HasDefaultValue(0.0m)
            .IsRequired();

        // RemainingDays is a persisted/computed column in SQL Server: (EntitledDays + CarriedOverDays - UsedDays - PendingDays)
        builder.Property(lb => lb.RemainingDays)
            .HasColumnType("decimal(4,1)")
            .ValueGeneratedOnAddOrUpdate();

        builder.Property(lb => lb.IsDeleted)
            .HasDefaultValue(false)
            .IsRequired();

        builder.Property(lb => lb.CreatedAt)
            .HasDefaultValueSql("GETDATE()")
            .IsRequired();

        builder.HasOne(lb => lb.Employee)
            .WithMany(e => e.LeaveBalances)
            .HasForeignKey(lb => lb.EmployeeId)
            .OnDelete(DeleteBehavior.Restrict);

        builder.HasOne(lb => lb.LeaveType)
            .WithMany(lt => lt.LeaveBalances)
            .HasForeignKey(lb => lb.LeaveTypeId)
            .OnDelete(DeleteBehavior.Restrict);

        // Unique index: One balance record per employee per leave type per year
        builder.HasIndex(lb => new { lb.EmployeeId, lb.LeaveTypeId, lb.LeaveYear })
            .IsUnique();
    }
}

